insert into "blog_general" ("path", "hs_name", "slug", "main_campaign", "campaign_value", "title", "thumbnail", "content", "conditions_title", "conditions", "conditions_title_1", "conditions_1", "conditions_title_2", "conditions_2", "cta_label", "cta_url", "show_inproject") values ('openacc-ytreward2026-upto400points', 'ลูกค้าใหม่เปิดพอร์ตลงทุนวันนี้ รับ Yuanta Rewards สูงสุดถึง 400 Points', 'Openacc-YTReward2026-Upto400Points', 'Blog', 'Blog-YTR26', 'ลูกค้าใหม่เปิดพอร์ตลงทุนวันนี้ รับ Yuanta Rewards สูงสุดถึง 400 Points', '{"url": "https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/25%20-%20YTR26-02.jpg", "width": 4454, "height": 2500, "altText": "25 - YTR26-02", "fileId": 379808165600, "type": "image"}'::jsonb, '<p style="line-height: 1.75; background-color: #ffffff;"><span style="font-family: Helvetica, Arial, sans-serif;"><strong><img src="https://43844850.fs1.hubspotusercontent-na2.net/hubfs/43844850/25%20-%20YTR26-02.jpg" width="4454" height="2500" loading="lazy" alt="25 - YTR26-02" style="height: auto; max-width: 100%; width: 4454px;"></strong></span></p>
<p style="line-height: 1.75; background-color: #ffffff;"><span style="font-family: Helvetica, Arial, sans-serif;"><strong>เปิดบัญชีออนไลน์ใหม่กับหยวนต้ากรอกโค้ด YTR26 </strong></span></p>
<p style="line-height: 1.75; background-color: #ffffff;"><span style="font-family: Helvetica, Arial, sans-serif;">ต่อที่ 1 : เทรดสะสมขั้นต่ำ 2,000 บาท รับ Yuanta Rewards 100 Point (มูลค่า 100 บาท)</span><br><span style="font-family: Helvetica, Arial, sans-serif;">ต่อที่ 2 : เทรดสะสมครบ 100,000 บาท รับเพิ่ม 100 Point (มูลค่า 100 บาท)</span><br><span style="font-family: Helvetica, Arial, sans-serif;">ต่อที่ 3 : เทรดสะสมครบ 500,000 บาท รับเพิ่มอีก 200 Point (มูลค่า 200 บาท)</span></p>
<p style="line-height: 1.75; background-color: #ffffff;"><span style="font-family: Helvetica, Arial, sans-serif;">เทรดสะสมภายใน 15 วันหลังเปิดบัญชีสำเร็จ จำกัด 200 บัญชี/เดือน </span><br><span style="font-family: Helvetica, Arial, sans-serif;">ระยะเวลาโปรโมชันตั้งแต่วันที่ 1 สิงหาคม 2569 – 31 ธันวาคม 2569</span></p>
<p style="line-height: 1.75; background-color: #ffffff;"><span style="font-family: Helvetica, Arial, sans-serif;"><strong>ขั้นตอนการเข้าร่วมกิจกรรม </strong></span><br><span style="font-family: Helvetica, Arial, sans-serif;">1. เปิดบัญชีใหม่ให้สำเร็จพร้อมกรอกโค้ด YTR26 </span><br><span style="font-family: Helvetica, Arial, sans-serif;">2 .เทรดสะสมผ่านบัญชีซื้อขายหลักทรัพย์ Cash Balance โดยผลิตภัณฑ์ที่เข้าร่วมได้แก่ หุ้นไทย, DR, ETF, Warrant และ DW </span><br><span style="font-family: Helvetica, Arial, sans-serif;">- เทรดสะสมขั้นต่ำ 2,000 บาท เพื่อรับ Yuanta Rewards 100 Point (มูลค่า 100 บาท)</span><br><span style="font-family: Helvetica, Arial, sans-serif;">- เทรดสะสมครบ 100,000 บาท เพื่อรับเพิ่ม 100 Point (มูลค่า 100 บาท)</span><br><span style="font-family: Helvetica, Arial, sans-serif;">- เทรดสะสมครบ 500,000 บาท เพื่อรับเพิ่ม 200 Point (มูลค่า 200 บาท)</span></p>
<p style="line-height: 1.5; background-color: #ffffff;">&nbsp;</p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">คำเตือน: การลงทุนมีความเสี่ยงผู้ลงทุนควรศึกษาทำความเข้าใจลักษณะสินค้า เงื่อนไข ก่อนตัดสินใจลงทุน</span></p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">บริษัทหลักทรัพย์ หยวนต้า (ประเทศไทย) จำกัด ได้รับใบอนุญาตจากกระทรวงการคลัง อยู่ภายใต้การกำกับดูแล</span></p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">ของสำนักงาน ก.ล.ต. ใบอนุญาตประกอบธุรกิจหลักทรัพย์เลขที่ ลก-0015-01</span><br><span style="font-family: Helvetica, Arial, sans-serif;"> </span></p>
<p style="background-color: #ffffff; line-height: 1;">&nbsp;</p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">ศึกษารายละเอียด หรือสอบถามเพิ่มเติมได้ที่ผู้แนะนำการลงทุนของท่าน หรือ ผ่านช่องทาง</span></p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">https://www.yuanta.co.th/</span></p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">Online Service: 0 2009 8000</span></p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">อีเมล: online@yuanta.co.th</span></p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">Facebook: Yuanta Securities Thailand</span></p>
<p style="background-color: #ffffff; line-height: 1;"><span style="font-family: Helvetica, Arial, sans-serif;">Line : @yuantathai</span></p>', 'คำถามที่พบบ่อย', '<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- เปิดบัญชีได้ที่ไหนบ้าง</span><br><span style="font-family: Helvetica, Arial, sans-serif;">เปิดบัญชีออนไลน์ผ่าน YSinvest ให้สำเร็จ หรือคลิก <a href="https://na2.hubs.ly/H06-YSd0"><u>https://na2.hubs.ly/H06-YSd0</u></a></span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- หากไม่ได้กรอกโค้ด YTR26 จะได้รับสิทธิ์หรือไม่</span><br><span style="font-family: Helvetica, Arial, sans-serif;">หากตอนเปิดบัญชีไม่ได้กรอกโค้ด YTR26 จะไม่สามารถเข้าร่วมและรับสิทธิ์ตามโปรโมชันนี้ได้</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- ต้องทำอย่างไรจึงจะได้รับสิทธิ์? </span><br><span style="font-family: Helvetica, Arial, sans-serif;">1. เปิดบัญชีออนไลน์ผ่าน YSinvest ให้สำเร็จ</span><br><span style="font-family: Helvetica, Arial, sans-serif;">2. กรอกโค้ด YTR26 ตอนเปิดบัญชี</span><br><span style="font-family: Helvetica, Arial, sans-serif;">3.เทรดสะสมได้ทุกช่องทางผ่าน บัญชี Cash Balance ให้ครบตามเงื่อนไขภายใน 15 วันหลังเปิดบัญชีสำเร็จ</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- ใครสามารถเข้าร่วมโปรโมชันได้บ้าง</span><br><span style="font-family: Helvetica, Arial, sans-serif;">: ลูกค้าใหม่ที่ ไม่เคยมีบัญชีกับบริษัทหลักทรัพย์หยวนต้า (ประเทศไทย) มาก่อน</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- เทรดอะไรนับยอดได้บ้าง?</span><br><span style="font-family: Helvetica, Arial, sans-serif;">: หุ้นไทย, DR, ETF, Warrant และ DW</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- ต้องเทรดเท่าไหร่ถึงจะได้ Yuanta rewards Points และลูกค้า 1 ท่าน สามารถรับ Yuanta rewards สูงสุดได้กี่พอยต์</span><br><span style="font-family: Helvetica, Arial, sans-serif;">: ยอดเทรดสะสม 2,000 บาท ได้รับ Yuanta Rewards 100 Points (มูลค่า 100 บาท)</span><br><span style="font-family: Helvetica, Arial, sans-serif;">ยอดเทรดสะสม 100,000 บาท ได้รับ Yuanta Rewards 100 Points (มูลค่า 100 บาท)</span><br><span style="font-family: Helvetica, Arial, sans-serif;">ยอดเทรดสะสม 500,000 บาท ได้รับ Yuanta Rewards 200 Points (มูลค่า 200 บาท)</span><br><span style="font-family: Helvetica, Arial, sans-serif;">ลูกค้า 1 ท่านมีสิทธิ์รับ Yuanta rewards รวมสูงสุด 400 Points มูลค่า 400 บาท</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- ต้องเทรดภายในกี่วัน?</span><br><span style="font-family: Helvetica, Arial, sans-serif;">: ต้องทำยอดเทรดสะสมภายใน 15 วันหลังจากเปิดบัญชีสำเร็จ</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- นับยอดเทรดสะสมอย่างไร?</span><br><span style="font-family: Helvetica, Arial, sans-serif;">: นับจากมูลค่าการซื้อขายสะสม ในบัญชี Cash Balance ไม่รวม ค่าคอมมิชชั่น VAT และค่าธรรมเนียมอื่นๆ</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- สามารถใช้สิทธิ์ร่วมกับโปรโมชันอื่นได้หรือไม่</span><br><span style="font-family: Helvetica, Arial, sans-serif;">: ไม่สามารถใช้ร่วมกับโปรโมชันเปิดบัญชีใหม่อื่น ๆ ของ บล.หยวนต้า ที่จัดขึ้นในช่วงเวลาเดียวกันได้</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- รับYuanta Reward ได้ตอนไหน </span><br><span style="font-family: Helvetica, Arial, sans-serif;">: ทุกโปรโมชัน ลูกค้าจะได้รับ Yuanta Rewards ภายใน 3 วันทำการนับจากที่ทำธุรกรรมสำเร็จ</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- ระยะเวลาโปรโมชันตั้งแต่วันไหนถึงวันไหน</span><br><span style="font-family: Helvetica, Arial, sans-serif;">: ตั้งแต่วันที่ 1 สิงหาคม 2569 – 31 ธันวาคม 2569</span></p>
<p style="line-height: 1.75;"><span style="font-family: Helvetica, Arial, sans-serif;">- วันสุดท้ายที่สามารถเปิดบัญชีและวันสุดท้ายที่สามารถเทรดได้ </span><br><span style="font-family: Helvetica, Arial, sans-serif;">: ลูกค้าจะต้องเปิดบัญชีให้แล้วเสร็จและได้รับการอนุมัติภายในวันที่ 31 ธันวาคม 2569 และทำรายการเทรดภายในวันที่ 15 มกราคม 2570 จึงจะมีสิทธิ์เข้าร่วมโปรโมชัน</span></p>', 'เงื่อนไขรายการส่งเสริมการขาย', '<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- ลูกค้าต้องเปิดบัญชีใหม่กับหยวนต้าผ่านระบบ YSinvest และกรอกโค้ด YTR26</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- สงวนสิทธิ์สำหรับลูกค้าใหม่ที่ไม่เคยมีบัญชีกับบริษัทหลักทรัพย์หยวนต้า (ประเทศไทย) จำกัด มาก่อน</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- ผู้เข้าร่วมต้องทำรายการเทรดสะสมให้ครบตามเงื่อนไขที่กำหนด ภายใน 15 วันหลังจากเปิดบัญชีสำเร็จ</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- ผู้เข้าร่วมต้องทำรายการเทรดสะสมผ่านบัญชีซื้อขายหลักทรัพย์ Cash Balance โดยผลิตภัณฑ์ที่เข้าร่วมได้แก่ หุ้นไทย, DR, ETF, Warrant และ DW</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- ยอดเทรดสะสมไม่นับรวม ค่าคอมมิชชั่น VATหรือค่าธรรมเนียมอื่นๆ</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- จำกัดสิทธิ์การเข้าร่วม 1 ท่านต่อ 1 สิทธิ์ จำกัด 200 สิทธิ์ต่อเดือน</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- บริษัทฯ ขอสงวนสิทธิ์ในการมอบหยวนต้าพอยต์เฉพาะผู้ที่ปฏิบัติตามเงื่อนไขครบถ้วนทุกประการ</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- สิทธิ์จะจัดสรรตามลำดับก่อน–หลังการทำรายการครบทุกขั้นตอน (First Come, First Served)</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- โปรโมชันนี้ไม่สามารถใช้ร่วมกับสิทธิประโยชน์หรือโปรโมชันส่งเสริมการขายอื่นของบริษัทฯ ได้</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- บริษัทฯ จะดำเนินการโอนหยวนต้าพอยต์ ให้ ลูกค้าภายใน 3 วันทำการนับจากวันที่ลูกค้าทำธุรกรรมสำเร็จ</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- หยวนต้าพอยต์ที่ได้รับไม่สามารถแลกเป็นเงินสด โอนสิทธิ์ หรือเปลี่ยนเป็นของรางวัลอื่นได้</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- วันที่มอบหยวนต้าพอยต์ บริษัทฯ ขอสงวนสิทธิ์ให้กับลูกค้าที่ยังคงสถานะการเป็นลูกค้าบริษัทฯ เท่านั้น </span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- บริษัทฯ ขอสงวนสิทธิ์ในการแก้ไข เปลี่ยนแปลง หรือยกเลิกเงื่อนไขการเข้าร่วม และ/หรือรายละเอียดของเงื่อนไขโปรโมชันนี้ ไม่ว่าทั้งหมดหรือบางส่วน รวมถึงเปลี่ยนแปลงของรางวัล/สิทธิพิเศษที่มีมูลค่าใกล้เคียงกันหรือเทียบเท่า โดยไม่ต้องแจ้งให้ทราบล่วงหน้า และการตัดสินของบริษัทฯ ถือเป็นที่สิ้นสุด</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- ผู้เข้าร่วมรายการส่งเสริมการขายนี้ รับทราบและตกลงที่จะผูกพันตามข้อกำหนดและเงื่อนไข และการตัดสินใจของบริษัทฯ โดยไม่มีข้อจำกัด ผู้เข้าร่วมการส่งเสริมการขายยอมรับว่าการพิจารณาของบริษัทฯ ถือเป็นที่สิ้นสุด</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- ขอสงวนสิทธิ์พนักงานของบริษัทฯ, คู่สมรส และบุตรที่ยังไม่บรรลุนิติภาวะ ไม่สามารถเข้าร่วมโปรโมชันนี้ได้</span></p>
<p style="line-height: 1.5;"><span style="font-family: Helvetica, Arial, sans-serif;">- ระยะเวลาโปรโมชัน: 1 สิงหาคม 2569 – 31 ธันวาคม 2569</span></p>', NULL, NULL, 'เปิดบัญชี', 'https://one.yuanta.co.th/signup', '[{"id": "1", "name": "template_default", "label": "Template default", "type": "option", "createdAt": "2026-08-19T03:49:28.564Z", "createdByUserId": 163508791, "updatedAt": "2026-08-19T03:49:28.564Z", "updatedByUserId": 163508791, "order": 0}]'::jsonb);